const home=document.getElementById('root').innerHTML;let timer;const slides=[['Trade Crypto Like a Pro','Our platform provides real-time market data and professional trading tools to maximize your returns.'],['Turn Idle Funds Into Powerful Assets','Experience seamless cryptocurrency trading with cutting-edge technology built for consistent performance.'],['Grow Your Wealth Faster','Explore the crypto market with powerful tools and a seamless trading experience.']];let active=0;function notice(text){document.querySelector('.notice')?.remove();let n=document.createElement('div');n.className='notice';n.setAttribute('role','status');n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),4500)}function initHome(){const hero=document.querySelector('section');if(!hero)return;let backgrounds=[...hero.children].filter(x=>x.className.includes('transition-opacity'));const buttons=[...hero.querySelectorAll('button')].filter(x=>!x.textContent.trim());function slide(n){active=(n+3)%3;backgrounds.forEach((x,i)=>{x.classList.toggle('opacity-100',i===active);x.classList.toggle('opacity-0',i!==active)});hero.querySelector('h1').textContent=slides[active][0];hero.querySelector('h1').nextElementSibling.textContent=slides[active][1];buttons.slice(2).forEach((b,i)=>{b.style.background=i===active?'#00ed87':'#555';b.setAttribute('aria-label','Show slide '+(i+1));b.setAttribute('aria-pressed',i===active)})}buttons.forEach((b,i)=>{b.setAttribute('aria-label',i===0?'Previous slide':i===1?'Next slide':'Show slide '+(i-1));b.onclick=()=>slide(i===0?active-1:i===1?active+1:i-2)});hero.querySelectorAll('button').forEach(b=>{if(/Google Play|App Store/.test(b.textContent))b.onclick=()=>notice('The mobile app is not available in this demo.')});slide(0);timer=setInterval(()=>slide(active+1),6500)}async function route(){clearInterval(timer);const page=location.hash.slice(2);if(page==='login'||page==='signup'){document.getElementById('root').outerHTML=await fetch('/'+page+'.html').then(r=>r.text());document.querySelectorAll('form').forEach(f=>{f.insertAdjacentHTML('afterbegin','<p class="demo-note">Demo recreation. Do not enter real credentials.</p>');f.onsubmit=e=>{e.preventDefault();notice('Demo only. Authentication is not connected.')}});document.querySelectorAll('input').forEach(i=>{i.autocomplete='off'});document.querySelectorAll('button').forEach(b=>{if(b.textContent.includes('🇺🇸'))b.onclick=e=>{e.preventDefault();notice('Demo phone prefix: +1')}})}else{document.getElementById('root').innerHTML=home;initHome();if(page==='markets')document.querySelector('table')?.scrollIntoView();else if(page==='trade')notice('Trading is not connected in this visual demo.');else if(page==='forgot-password')notice('Password recovery is not connected in this demo.');else window.scrollTo(0,0)}}window.addEventListener('hashchange',route);let badge=document.createElement('div');badge.className='demo-badge';badge.textContent='DEMO RECREATION · Sample market data';document.body.append(badge);route();